import { describe, expect, it } from "vitest";

import { parseMatrix, platformOf, rigRefProblem, rigResults, rigState } from "./matrix.ts";

const MATRIX = `# The support matrix

<!-- matrix:begin (generated by rig/bin/matrix.py: do not edit by hand) -->

3 passed, 1 failed (generated 2026-11-11T10:34:44+00:00). ✅ pass · ❌ fail · \`·\` not run.

| OS | Setup | Containers | VMs | App E2E |
|---|---|---|---|---|
| **windows-11** | golden | · |  | ❌ |
|  | golden:hyperv |  | ⏭ |  |
| **debian-13** | golden | ✅ |  | ✅ |
|  | golden:libvirt |  | ✅ |  |
|  | qemu |  | · |  |

**Not run, and why**

<!-- matrix:end -->
`;

describe("parseMatrix", () => {
  const rig = parseMatrix(MATRIX);

  it("reads the columns by their titles, each row's OS (carried down) and setup, and when it was made", () => {
    expect(rig.generated).toBe("2026-11-11T10:34:44+00:00");
    expect(rig.columns).toEqual(["container", "vm", "desktop-e2e"]);
    expect(rig.rows[0]).toEqual({ os: "windows-11", setup: "golden", cells: { container: "notrun", "desktop-e2e": "fail" } });
    expect(rig.rows.map((r) => `${r.os}/${r.setup}`)).toEqual([
      "windows-11/golden",
      "windows-11/golden:hyperv",
      "debian-13/golden",
      "debian-13/golden:libvirt",
      "debian-13/qemu",
    ]);
  });

  it("refuses a column it doesn't know and a file with no generated matrix", () => {
    expect(() => parseMatrix(MATRIX.replace("| VMs |", "| Mainframes |"))).toThrow(/unknown matrix column "Mainframes"/);
    expect(() => parseMatrix("# nothing")).toThrow(/no generated matrix/);
  });

  it("picks rows by what readied them: exactly, or by the hypervisor after the colon", () => {
    expect(rigResults(rig, ["vm@qemu"], null)).toEqual(["notrun"]);
    expect(rigResults(rig, ["vm@libvirt", "vm@golden:hyperv"], null)).toEqual(["pass", "skip"]);
    expect(rigResults(rig, ["vm"], "linux")).toEqual(["pass", "notrun"]);
  });

  it("says when a reference names no cell", () => {
    expect(rigRefProblem(rig, "vm@libvirt")).toBeNull();
    expect(rigRefProblem(rig, "cloud")).toBe("no rig column cloud (known: container, vm, desktop-e2e)");
    expect(rigRefProblem(rig, "container@libvirt")).toBe("no rig row readied by libvirt has a container cell");
  });

  it("says how a platform's cells last went, best first", () => {
    expect(rigState(rig, ["container", "desktop-e2e"], "windows")).toBe("fail");
    expect(rigState(rig, ["vm"], "windows")).toBe("skip");
    expect(rigState(rig, ["container"], "linux")).toBe("pass");
    expect(rigState(rig, ["vm"], "macos")).toBe("none");
  });
});

describe("platformOf", () => {
  it("reads an OS row's platform", () => {
    expect(["windows-11-arm64", "macos-x64", "kali-rolling"].map(platformOf)).toEqual(["windows", "macos", "linux"]);
  });
});
